package run.ikaros.reading;
import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentReadingProgressService implements ReadingProgressService {private final ReadingWorkRepository works;private final ReadingEditionRepository editions;private final ReadingChapterRepository chapters;private final ReadingSessionRepository sessions;private final ReadingProgressRepository progress;private final ReadingHistoryRepository history;public PersistentReadingProgressService(ReadingWorkRepository w,ReadingEditionRepository e,ReadingChapterRepository c,ReadingSessionRepository s,ReadingProgressRepository p,ReadingHistoryRepository h){works=w;editions=e;chapters=c;sessions=s;progress=p;history=h;}
 @Override public Mono<ReadingSessionView> start(UUID o,UUID workId,StartReadingSessionRequest r){return ownedWork(o,workId).then(editions.findById(r.editionId()).filter(e->e.ownerId().equals(o)&&e.workId().equals(workId)).switchIfEmpty(Mono.error(new NotFoundException("Edition 不存在或无权访问")))).then(chapters.findById(r.chapterId()).filter(c->c.ownerId().equals(o)&&c.editionId().equals(r.editionId())).switchIfEmpty(Mono.error(new NotFoundException("Chapter 不存在或不属于该 Edition")))).flatMap(c->{Instant now=Instant.now();return sessions.save(new ReadingSessionEntity(null,o,workId,r.editionId(),c.id(),c.id(),r.locatorKind(),r.locatorValue(),r.locatorKind(),r.locatorValue(),now,now,null,r.offline(),null));}).map(this::sessionView);}
 @Override public Mono<ReadingSessionView> update(UUID o,UUID id,UpdateReadingProgressRequest r){return active(o,id).flatMap(s->{Instant now=Instant.now();return sessions.save(new ReadingSessionEntity(s.id(),s.ownerId(),s.workId(),s.editionId(),s.startedChapterId(),s.currentChapterId(),s.startedLocatorKind(),s.startedLocatorValue(),r.locatorKind(),r.locatorValue(),s.startedAt(),now,null,s.offline(),s.version())).flatMap(u->saveProgress(o,u,r).thenReturn(u));}).map(this::sessionView);}
 private Mono<ReadingProgressEntity> saveProgress(UUID o,ReadingSessionEntity s,UpdateReadingProgressRequest r){return progress.findByOwnerIdAndWorkIdAndEditionId(o,s.workId(),s.editionId()).flatMap(p->progress.save(new ReadingProgressEntity(p.id(),o,s.workId(),s.editionId(),s.currentChapterId(),r.locatorKind(),r.locatorValue(),r.contentVersion(),r.completed(),r.intent()==null?ReadingProgressIntent.PROGRESS_FORWARD:r.intent(),s.id(),Instant.now(),p.version()))).switchIfEmpty(progress.save(new ReadingProgressEntity(null,o,s.workId(),s.editionId(),s.currentChapterId(),r.locatorKind(),r.locatorValue(),r.contentVersion(),r.completed(),r.intent()==null?ReadingProgressIntent.PROGRESS_FORWARD:r.intent(),s.id(),Instant.now(),null)));}
 @Override public Mono<ReadingSessionView> end(UUID o,UUID id){return active(o,id).flatMap(s->{Instant now=Instant.now();return sessions.save(new ReadingSessionEntity(s.id(),s.ownerId(),s.workId(),s.editionId(),s.startedChapterId(),s.currentChapterId(),s.currentLocatorKind(),s.currentLocatorValue(),s.currentLocatorKind(),s.currentLocatorValue(),s.startedAt(),now,now,s.offline(),s.version())).flatMap(u->history.save(new ReadingHistoryEntity(null,o,s.workId(),s.currentChapterId(),s.startedAt(),now,Math.max(0,now.getEpochSecond()-s.startedAt().getEpochSecond()),s.startedLocatorKind()+":"+s.startedLocatorValue(),s.currentLocatorKind()+":"+s.currentLocatorValue())).thenReturn(u));}).map(this::sessionView);}
 @Override public Mono<ReadingProgressView> progress(UUID o,UUID workId,UUID editionId){return ownedWork(o,workId).then(progress.findByOwnerIdAndWorkIdAndEditionId(o,workId,editionId).switchIfEmpty(Mono.error(new NotFoundException("Reading Progress 不存在"))).map(this::progressView));}@Override public Flux<ReadingHistoryView> history(UUID o){return history.findAllByOwnerIdOrderByEndedAtDesc(o).map(this::historyView);}private Mono<ReadingWorkEntity> ownedWork(UUID o,UUID id){return works.findById(id).filter(w->w.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Reading Work 不存在或无权访问")));}private Mono<ReadingSessionEntity> active(UUID o,UUID id){return sessions.findById(id).filter(s->s.ownerId().equals(o)).switchIfEmpty(Mono.error(new NotFoundException("Reading Session 不存在"))).flatMap(s->s.endedAt()==null?Mono.just(s):Mono.error(new ConflictException("Reading Session 已结束")));}private ReadingSessionView sessionView(ReadingSessionEntity s){return new ReadingSessionView(s.id(),s.workId(),s.editionId(),s.currentChapterId(),s.currentLocatorKind(),s.currentLocatorValue(),s.offline(),s.startedAt(),s.lastActiveAt(),s.endedAt());}private ReadingProgressView progressView(ReadingProgressEntity p){return new ReadingProgressView(p.id(),p.workId(),p.editionId(),p.chapterId(),p.locatorKind(),p.locatorValue(),p.contentVersion(),p.completed(),p.intent(),p.updatedAt(),p.version()==null?0:p.version());}private ReadingHistoryView historyView(ReadingHistoryEntity h){return new ReadingHistoryView(h.id(),h.workId(),h.chapterId(),h.startedAt(),h.endedAt(),h.durationSeconds(),h.startLocator(),h.endLocator());}}
